    date: "২০২৬",
    content: `রাত শেষে আমি নিজের সাথেই কথা বলি। দিনের ব্যস্ততা শেষে যখন সব কিছু থমকে যায়, তখন নিজের চিন্তা আর অনুভূতিতে ফিরে আসি।

অনেক সময়ই মানুষ বাইরে অনেক কথা বলে, অনেক মুখোশ পরে, কিন্তু সত্যিকার আমি রাত শেষে নিজেকেই পাই। নিজেকে বুঝতে পারা কঠিন, কিন্তু প্রয়োজন।

রাতের নির্জনতায় আমি বুঝি কোথায় ভুল করেছি, কোথায় ভালো কাজ করেছি। এতে আমায় নিজের প্রতি সম্মান বাড়ে।

রাতে নিজেকে পাওয়া মানে নিজেকে শান্তি দেওয়া। `,
