    date: "২০২৬",
    content: `জীবনের পথে কিছু সময় এমন আসে,
যখন কাউকে খুব করে প্রয়োজন হয়,
তবুও কাউকে ডাকার মতো সাহস হয় না।
আমি অনেকবার হাত বাড়াতে চেয়েছি,
কিন্তু মাঝপথেই থেমে গেছি—
কারণ আমি জানতাম, সেই হাত ধরা হবে না।

মানুষের ভিড়ে থেকেও একা লাগতে পারে—
এই সত্যটা আমি ধীরে ধীরে শিখেছি।
চারপাশে অনেক মুখ থাকে,
কিন্তু সব মুখে নিজের জন্য জায়গা থাকে না।

তাই এখন আর সহজে কারো ওপর ভরসা করি না,
সব অনুভূতি সবার সামনে মেলে ধরি না;
কারণ আমি জানি,
সবাই অনুভূতির ওজন বুঝতে পারে না।

শেষ পর্যন্ত মানুষ নিজের কাছেই ফিরে আসে,
আর নিজের সঙ্গে মানিয়ে নিতে শেখে।`,
