    date: "২০২৬",
    content: `আমাকে কি পারতে না নিজের করে রাখতে?
এত সহজে কী করে ছেড়ে দেওয়া যায় কাউকে,
যাকে একসময় নিজের চেয়েও বেশি চাওয়া হয়েছিল?

আমি তো খুব বেশি কিছু চাইনি,
শুধু একটু জায়গা চেয়েছিলাম তোমার পাশে—
যেখানে নিশ্চিন্তে বলতে পারতাম, এই মানুষটা আমার।

তুমি চাইলে গল্পটা অন্যরকম হতে পারতো,
আমরা হয়তো হারিয়ে যেতাম না এভাবে;
কিছু স্মৃতি এখনো বেঁচে থাকতো
একসঙ্গে থাকার প্রমাণ হয়ে।

কিন্তু তুমি তো বেছে নিলে দূরত্ব,
আর আমি শিখে গেলাম ছেড়ে দিতে—
কারণ ধরে রাখার চেষ্টায়
আমি নিজেকেই হারিয়ে ফেলছিলাম।

শেষে শুধু একটা প্রশ্ন রয়ে গেলো—
আমাকে কি পারতে না নিজের করে রাখতে?`,
