    date: "২০২৬",
    content: `আমি মানুষ হতে পারিনি,
মানুষের রূপে থাকলেও আমি মূলত পাথর।
একসময় ছোট ছোট ব্যাপারে ভেতরটা নড়ে উঠত,
এখন বড় কিছুতেও তেমন ছুঁতে পারে না,
কারণ নিজেকে ধীরে ধীরে শক্ত করে নিয়েছি।

আমার অনুভূতি নেই—এমন নয়,
আসলে তা প্রকাশ করার ইচ্ছে হারিয়ে গেছে।
কেউ কষ্ট দিলে আর ভেঙে পড়ি না,
শুধু চুপ হয়ে যাই নিজের ভেতরেই।

আমি বদলে গেছি—এটা সত্যি,
কিন্তু এই বদলে যাওয়া আমার পছন্দ ছিল না।
বারবার ভেঙে যেতে যেতে
একসময় নিজেকে এমন করেই গড়ে নিতে হয়েছে।

আমাকে এখন আর কিছুই সহজে নাড়াতে পারে না,
কারণ আমি জানি—
যত বেশি অনুভব করবো, তত বেশি নিজেকে হারাবো।`,
