    content: `তুমি আমাকে শেষ উপহার হিসেবে একটা বই দিয়েছিলে। আমি বইটা অনেক যত্ন করে রেখে দিয়েছিলাম। পড়িনি। কারণ পড়লে মনে হবে, তুমি শেষ হয়ে গেছো।

আজ বইটা খুললাম। প্রথম পাতায় তোমার হাতের লেখা — "তোমার জন্য।" শুধু এটুকুই। কিন্তু এই দুটো শব্দ পড়ে আমি অনেকক্ষণ চুপ করে বসে রইলাম।

তুমি কি জানতে, এই বইটা আমি অনেকদিন পরে পড়বো? তুমি কি জানতে, তখন তুমি আর থাকবে না? তুমি কি জেনেশুনেই এই দুটো শব্দ লিখেছিলে?`,
