    content: `অপ্রাপ্তি
তুমি অনেক কিছু চেয়েও কখনো পেতে পারো না। এই অপ্রাপ্তি কখনো তোমায় ভগ্ন করে, কখনো তোমায় চিন্তায় ডুবায়। কিন্তু অপ্রাপ্তি মানেই জীবনের এক বিরাট পাঠ, যা তোমাকে শেখায় ধৈর্য ধরতে ও নিজেকে আরও মজবুত করতে।

যেখানে তুমি কিছু পেতে পারোনি, সেই শূন্যতাটিও তোমার জন্য নতুন দিশার সূচনা। তুমি বুঝতে পারো, সবকিছুই তোমার নিয়ন্ত্রণে নেই, আর তাই তোমাকে নিজের সীমাবদ্ধতাগুলো মেনে নিতে হয়।

অপ্রাপ্তি তোমায় নতুন করে স্বপ্ন দেখায়, নতুন পথ খুঁজতে শেখায়, যা জীবনের অঙ্গীকারে পরিণত হয়।`,
